    "year": "2018-2019 (Bütünleme)",
    "q_num": 165,
    "subject": "Histoloji ve Embriyoloji",
    "professor": "Belirtilmemiş",
    "question": "ens, irıs epıteli ve Dilatör pupılla kasları'nın embrıyonik kökenken sırsıyla hangi seçenekte doğru ifade edilmıştır?",
    "options": [
      {
        "letter": "A",
        "text": "Yüzey ektoderm - Nöral Ektoderm - Nöral krista"
      },
      {
        "letter": "B",
        "text": "Yüzey ektoderm - Nöral Ektoderm - Nöral Ektoderm"
      },
      {
        "letter": "C",
        "text": "Nöral Ektoderm - Nöral Ektoderm - Mezoderm"
      },
      {
        "letter": "D",
        "text": "Nöral Ektoderm - Yüzey ektoderm - Nöral Krista"
      },
      {
        "letter": "E",
        "text": "Mezoderm - Nöral krista - Nöral krista"
      }
    ],
    "answer": "B",
    "open_answer": "",
